content.content:
1	== V1__sheet.sql
2	-- A sheet's own settings. A sheet with no row here has never been changed: its today is the real date.
3	CREATE TABLE sheet (
4	    id         VARCHAR(255) PRIMARY KEY,
5	    today_date DATE NOT NULL
6	);
7	== V2__person.sql
8	-- The people on a sheet, listed in the order they were added (by id).
9	CREATE TABLE person (
10	    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
11	    sheet_id VARCHAR(255) NOT NULL,
12	    name     VARCHAR(255) NOT NULL,
13	    grade    VARCHAR(1)   NOT NULL
14	);
15	CREATE INDEX person_sheet ON person (sheet_id, id);
16	== V3__person_name_unique.sql
17	-- A person's name is unique on the sheet, compared without regard to case. Names are stored without
18	-- surrounding spaces; name_key is the lower-cased name the uniqueness is kept on.
19	UPDATE person SET name = TRIM(name);
20	ALTER TABLE person ADD COLUMN name_key VARCHAR(255) GENERATED ALWAYS AS (LOWER(name));
21	ALTER TABLE person ADD CONSTRAINT person_sheet_name UNIQUE (sheet_id, name_key);
22	== V4__claim.sql
23	-- A person's claims on a sheet, listed newest first (by id). The amount is 0.00 or more, in two
24	-- decimals; claim_date defaults to the sheet's today when the claim is made.
25	CREATE TABLE claim (
26	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
27	    sheet_id   VARCHAR(255)   NOT NULL,
28	    person_id  BIGINT         NOT NULL REFERENCES person (id),
29	    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
30	    claim_date DATE           NOT NULL,
31	    note       VARCHAR(4000)  NOT NULL
32	);
33	CREATE INDEX claim_sheet ON claim (sheet_id, id);
34	== V5__rate.sql
35	-- A sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
36	CREATE TABLE rate (
37	    sheet_id VARCHAR(255)  NOT NULL,
38	    grade    VARCHAR(1)    NOT NULL,
39	    rate     DECIMAL(9, 2) NOT NULL CHECK (rate >= 0),
40	    PRIMARY KEY (sheet_id, grade)
41	);
42	== V6__claim_status.sql
43	-- A claim's status: DRAFT when made; OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID.
44	-- Only OPEN and SETTLED claims count toward the totals.
45	ALTER TABLE claim ADD COLUMN status VARCHAR(16) DEFAULT 'DRAFT' NOT NULL;
46	== V7__claim_number.sql
47	-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused.
48	-- A draft has none; voiding a claim clears it. claim_number_seq holds the last number each sheet gave.
49	ALTER TABLE claim ADD COLUMN claim_number BIGINT;
50	CREATE TABLE claim_number_seq (
51	    sheet_id    VARCHAR(255) PRIMARY KEY,
52	    last_number BIGINT NOT NULL
53	);
54	== V8__claim_settled_due.sql
55	-- A settled claim's due, fixed when it was settled: its amount times its person's grade's rate at that
56	-- moment. Null for a claim not settled, or settled while the grade had no rate (its due stays live).
57	ALTER TABLE claim ADD COLUMN settled_due DECIMAL(15, 2);
58	== V9__rate_from.sql
59	-- A rate may carry a from-date: a grade may have several rates, one per from-date. A rate with no
60	-- from-date (null) applies from the beginning of time. At most one rate per grade and from-date.
61	ALTER TABLE rate DROP PRIMARY KEY;
62	ALTER TABLE rate ADD COLUMN from_date DATE;
63	CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
64	== V10__claim_opened_by.sql
65	-- Who opened the claim: the signed-in user named by the open. Null for a claim never opened.
66	-- The user who opened a claim cannot settle it.
67	ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
68	== V11__person_version.sql
69	-- The version of a person, raised on every edit. An edit names the version its form loaded and is
70	-- refused when the person has been saved since.
71	ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
72	== V12__statement.sql
73	-- A claim bound by its person's last statement: stated, at the figure it had then (stated_due; null when it
74	-- had none). It shows and totals that figure until the person's next statement, which rebinds every claim
75	-- of theirs that counts then and leaves the rest unbound.
76	ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
77	ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
78	
79	-- The statements taken of a person, in the order taken (by id): their due-total then ("n/a" when it had
80	-- none), how many of their claims counted, and the sheet's today when it was taken.
81	CREATE TABLE statement (
82	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
83	    sheet_id   VARCHAR(255) NOT NULL,
84	    person_id  BIGINT       NOT NULL REFERENCES person (id),
85	    due_total  VARCHAR(32)  NOT NULL,
86	    claims     INT          NOT NULL,
87	    stated_on  DATE         NOT NULL
88	);
89	CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
90	== V13__period.sql
91	-- A sheet's periods: a name unique on the sheet and a from and to date, inclusive. No two periods
92	-- of a sheet overlap (checked when one is added).
93	CREATE TABLE period (
94	    sheet_id  VARCHAR(255) NOT NULL,
95	    name      VARCHAR(255) NOT NULL,
96	    from_date DATE         NOT NULL,
97	    to_date   DATE         NOT NULL,
98	    CHECK (from_date <= to_date),
99	    PRIMARY KEY (sheet_id, name)
100	);
101	== V14__period_closed.sql
102	-- A period can be closed. Closing fixes its due-total at that moment: closed_total is that figure
103	-- (null while the period is open), and later changes to rates do not alter it.
104	ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
105	ALTER TABLE period ADD COLUMN closed_total DECIMAL(15, 2);
106	== V15__person_retired.sql
107	-- The date a person is retired from (null when not retired). A person with one set counts as retired
108	-- at once, whatever the date; claims dated after it are refused.
109	ALTER TABLE person ADD COLUMN retired_from DATE;
110	== V16__person_held.sql
111	-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own, the
112	-- sheet's or a period's); their SETTLED claims still count.
113	ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
114	== V17__setting_role.sql
115	-- A sheet's settings, one value per key (clerk-limit: an amount with two decimals). A key with no
116	-- row, or a blank value, is not set (a clerk limit not set is no limit).
117	CREATE TABLE setting (
118	    sheet_id      VARCHAR(255) NOT NULL,
119	    setting_key   VARCHAR(64)  NOT NULL,
120	    setting_value VARCHAR(255) NOT NULL,
121	    PRIMARY KEY (sheet_id, setting_key)
122	);
123	-- The role a sheet gives a user name: clerk or steward. A name with no row is a clerk.
124	CREATE TABLE sheet_role (
125	    sheet_id  VARCHAR(255) NOT NULL,
126	    user_name VARCHAR(255) NOT NULL,
127	    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward')),
128	    PRIMARY KEY (sheet_id, user_name)
129	);
130	== V18__person_patron.sql
131	-- The people a person names as their patrons: other people on the same sheet, each at most once.
132	CREATE TABLE person_patron (
133	    person_id BIGINT NOT NULL,
134	    patron_id BIGINT NOT NULL,
135	    PRIMARY KEY (person_id, patron_id)
136	);
137	== V19__person_grade_from.sql
138	-- A person's grade is dated: person.grade is the first grade they were given, which applies from the
139	-- beginning of time; each row here is a grade they were given from a date on. At most one per date.
140	CREATE TABLE person_grade (
141	    person_id BIGINT     NOT NULL,
142	    from_date DATE       NOT NULL,
143	    grade     VARCHAR(1) NOT NULL,
144	    PRIMARY KEY (person_id, from_date)
145	);
146	== V20__claim_corrects.sql
147	-- A correction (a claim with a negative amount) names, by number, the SETTLED claim of the same person it
148	-- corrects; null for any other claim. The amount's old "0 or more" check (unnamed) goes with its column, which is
149	-- rebuilt so that only a correction may be negative.
150	ALTER TABLE claim ADD COLUMN corrects BIGINT;
151	ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(15, 2);
152	UPDATE claim SET amount_signed = amount;
153	ALTER TABLE claim DROP COLUMN amount;
154	ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
155	ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
156	ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
157	== V21__claim_period_number.sql
158	-- A claim's number becomes text: the sheet-wide 1, 2, ... or, while the sheet numbers by period, <period>-<n>
159	-- (X-<n> for a claim in no period). A correction names the number it corrects the same way.
160	-- claim_period_number_seq holds the last number each sheet gave in each period ('' is the no-period sequence).
161	ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(300);
162	ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(300);
163	CREATE TABLE claim_period_number_seq (
164	    sheet_id    VARCHAR(255) NOT NULL,
165	    scope       VARCHAR(255) NOT NULL,
166	    last_number BIGINT       NOT NULL,
167	    PRIMARY KEY (sheet_id, scope)
168	);
169	== V22__claim_listed.sql
170	-- Where a claim stands in its sheet's newest-first list: the next on its sheet when it is made, and again
171	-- when it is reassigned to another person, so a moved claim lists as its new person's newest whatever its date.
172	ALTER TABLE claim ADD COLUMN listed BIGINT;
173	UPDATE claim SET listed = id;
174	ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
175	CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
176	== V23__claim_due_by.sql
177	-- A claim's due-by, fixed when it is made: its date plus the terms of its person's grade on that date
178	-- (the sheet's terms when the grade has none of its own). Claims made before terms were kept per grade
179	-- are due by their date plus the sheet's terms (14 when never set).
180	ALTER TABLE claim ADD COLUMN due_by DATE;
181	UPDATE claim c SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.setting_value AS INT) FROM setting s
182	    WHERE s.sheet_id = c.sheet_id AND s.setting_key = 'terms' AND s.setting_value <> ''), 14), c.claim_date);
183	ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
184	== V24__claim_log.sql
185	-- A claim's status log, oldest first (by id): each status it has had, who gave it, the sheet's today then,
186	-- and its due as shown at that moment ("n/a" when it had none). Claims made before the log have none.
187	CREATE TABLE claim_log (
188	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
189	    sheet_id  VARCHAR(255) NOT NULL,
190	    claim_id  BIGINT       NOT NULL REFERENCES claim (id),
191	    status    VARCHAR(16)  NOT NULL,
192	    by_user   VARCHAR(255) NOT NULL,
193	    logged_on DATE         NOT NULL,
194	    due       VARCHAR(32)  NOT NULL
195	);
196	CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
197	== V25__person_hold.sql
198	-- A person's holds, each from its from-date to its to-date inclusive (no to-date: open-ended). A person may
199	-- have several over time. Only their OPEN (and PENDING) claims dated within a hold and not bound by a statement
200	-- are left out of the live totals. A person held before holds were dated is held from the beginning of time.
201	CREATE TABLE person_hold (
202	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
203	    person_id BIGINT NOT NULL REFERENCES person (id),
204	    from_date DATE   NOT NULL,
205	    to_date   DATE
206	);
207	CREATE INDEX person_hold_person ON person_hold (person_id, from_date);
208	INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
209	ALTER TABLE person DROP COLUMN held;
210	== V26__rate_to.sql
211	-- A rate may carry a to-date: it applies through that date (null: with no end). Never before its from-date.
212	ALTER TABLE rate ADD COLUMN to_date DATE;
213	== V27__period_person_total.sql
214	-- Closing a period fixes each person's due-total for it too: one row per person on the sheet at that
215	-- moment. Reopening drops them; a person added while it is closed has no row (their figure is 0.00).
216	CREATE TABLE period_person_total (
217	    sheet_id    VARCHAR(255)   NOT NULL,
218	    period_name VARCHAR(255)   NOT NULL,
219	    person_id   BIGINT         NOT NULL,
220	    total       DECIMAL(15, 2) NOT NULL,
221	    PRIMARY KEY (sheet_id, period_name, person_id)
222	);
223	== V28__setting_from.sql
224	-- A setting that carries a figure (the clerk limit, the floor, the terms and each grade's terms, the late percent,
225	-- the cap) is dated: one value per from-date, in force from that date until the next one. A blank value is none
226	-- (no clerk limit, no cap). The policy date and the period numbering from-date stay undated, in setting.
227	CREATE TABLE setting_from (
228	    sheet_id      VARCHAR(255) NOT NULL,
229	    setting_key   VARCHAR(64)  NOT NULL,
230	    from_date     DATE         NOT NULL,
231	    setting_value VARCHAR(255) NOT NULL,
232	    PRIMARY KEY (sheet_id, setting_key, from_date)
233	);
234	-- A value saved before settings were dated was in force on every date.
235	INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
236	    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM setting
237	    WHERE setting_key IN ('clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap');
238	DELETE FROM setting
239	    WHERE setting_key IN ('clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap');
240	== V29__claim_deferred_until.sql
241	-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches it the claim counts
242	-- in no total, is not overdue, cannot be settled and is left unbound by a statement. Null: never deferred.
243	ALTER TABLE claim ADD COLUMN deferred_until DATE;
244	== V30__claim_proofs.sql
245	-- How many proofs a claim has been given, raised by one at a time; 0 for a claim given none.
246	ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
247	== V31__role_viewer.sql
248	-- A third role, viewer: sees everything and may change nothing. The role check is rebuilt to allow it.
249	CREATE TABLE sheet_role_new (
250	    sheet_id  VARCHAR(255) NOT NULL,
251	    user_name VARCHAR(255) NOT NULL,
252	    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
253	    PRIMARY KEY (sheet_id, user_name)
254	);
255	INSERT INTO sheet_role_new (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
256	DROP TABLE sheet_role;
257	ALTER TABLE sheet_role_new RENAME TO sheet_role;
258	== V32__claim_split_from.sql
259	-- A claim split off another names, by number, the claim it was split from; null for any other claim.
260	ALTER TABLE claim ADD COLUMN split_from VARCHAR(64);
261	== V33__person_watch.sql
262	-- Who watches whom: one row per signed-in user watching a person, in the order they started watching
263	-- (id). Unwatching deletes the row, so watching again starts afresh at the end.
264	CREATE TABLE person_watch (
265	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
266	    person_id BIGINT       NOT NULL REFERENCES person (id),
267	    user_name VARCHAR(255) NOT NULL
268	);
269	CREATE INDEX person_watch_person ON person_watch (person_id, id);
270	== V34__delegation.sql
271	-- A steward's delegation of the steward role to a user name, from a from-date to a to-date (inclusive). While the
272	-- sheet's today is inside the range the user acts as a steward; delegated_by is the steward who delegated.
273	CREATE TABLE delegation (
274	    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
275	    sheet_id     VARCHAR(255) NOT NULL,
276	    user_name    VARCHAR(255) NOT NULL,
277	    from_date    DATE         NOT NULL,
278	    to_date      DATE         NOT NULL,
279	    delegated_by VARCHAR(255) NOT NULL
280	);
281	CREATE INDEX delegation_sheet ON delegation (sheet_id, user_name);
282	== V35__sheet_archived.sql
283	-- An archived sheet keeps everything visible and refuses every change. Only a steward archives a sheet.
284	ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
285	== V36__person_terms.sql
286	-- A person's own terms in days, which come before those of their grade and of the sheet; null for none.
287	ALTER TABLE person ADD COLUMN terms INT;
288	== V37__claim_lock.sql
289	-- A claim whose editor a user has open: locked for every other user until saved or cancelled, or the sheet's today changes.
290	CREATE TABLE claim_lock (
291	    claim_id  BIGINT       PRIMARY KEY REFERENCES claim (id),
292	    sheet_id  VARCHAR(255) NOT NULL,
293	    locked_by VARCHAR(255) NOT NULL
294	);
295	CREATE INDEX claim_lock_sheet ON claim_lock (sheet_id);
296	== V38__period_soft_close.sql
297	-- A period can be soft-closed: its due-total (closed_total) and its people's figures (period_person_total) are fixed,
298	-- but claims dated in it can still change. A claim added while its period is soft-closed is a late entry.
299	ALTER TABLE period ADD COLUMN soft BOOLEAN DEFAULT FALSE NOT NULL;
300	ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
301	== V39__history.sql
302	-- The history of the rows a person's figures are worked out from: every row a change writes to claim, person,
303	-- person_grade, person_hold, rate, setting or setting_from is copied to <table>_history (by the Journal trigger) with
304	-- the sheet's today when the change was made (history_on), in the order made (history_seq); a deleted row is copied
305	-- as it was, marked history_gone. A statement taken as of a date reads these tables back: each row as its last copy
306	-- made on or before that date left it. A column added to one of these tables must be added to its history too.
307	-- Rows stored before the history was kept were made at the beginning of time.
308	CREATE TABLE claim_history AS SELECT * FROM claim;
309	CREATE TABLE person_history AS SELECT * FROM person;
310	CREATE TABLE person_grade_history AS SELECT * FROM person_grade;
311	CREATE TABLE person_hold_history AS SELECT * FROM person_hold;
312	CREATE TABLE rate_history AS SELECT * FROM rate;
313	CREATE TABLE setting_history AS SELECT * FROM setting;
314	CREATE TABLE setting_from_history AS SELECT * FROM setting_from;
315	
316	ALTER TABLE claim_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
317	ALTER TABLE claim_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
318	ALTER TABLE claim_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
319	ALTER TABLE person_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
320	ALTER TABLE person_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
321	ALTER TABLE person_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
322	ALTER TABLE person_grade_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
323	ALTER TABLE person_grade_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
324	ALTER TABLE person_grade_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
325	ALTER TABLE person_hold_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
326	ALTER TABLE person_hold_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
327	ALTER TABLE person_hold_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
328	ALTER TABLE rate_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
329	ALTER TABLE rate_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
330	ALTER TABLE rate_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
331	ALTER TABLE setting_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
332	ALTER TABLE setting_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
333	ALTER TABLE setting_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
334	ALTER TABLE setting_from_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
335	ALTER TABLE setting_from_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
336	ALTER TABLE setting_from_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
337	
338	CREATE INDEX claim_history_key ON claim_history (sheet_id, id);
339	CREATE INDEX person_history_key ON person_history (sheet_id, id);
340	CREATE INDEX person_grade_history_key ON person_grade_history (person_id, from_date);
341	CREATE INDEX person_hold_history_key ON person_hold_history (person_id, id);
342	CREATE INDEX rate_history_key ON rate_history (sheet_id, grade);
343	CREATE INDEX setting_history_key ON setting_history (sheet_id, setting_key);
344	CREATE INDEX setting_from_history_key ON setting_from_history (sheet_id, setting_key);
