347	CREATE TRIGGER person_journal AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
348	CREATE TRIGGER person_grade_journal AFTER INSERT, UPDATE, DELETE ON person_grade FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
349	CREATE TRIGGER person_hold_journal AFTER INSERT, UPDATE, DELETE ON person_hold FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
