376	ALTER TABLE period_person_total_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
377	ALTER TABLE period_person_total_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
378	ALTER TABLE period_person_total_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
379	ALTER TABLE claim_log_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
380	ALTER TABLE claim_log_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
381	ALTER TABLE claim_log_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
382	ALTER TABLE person_patron_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
383	ALTER TABLE person_patron_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
384	ALTER TABLE person_patron_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
385	ALTER TABLE person_watch_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
386	ALTER TABLE person_watch_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
387	ALTER TABLE person_watch_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
388	ALTER TABLE delegation_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
389	ALTER TABLE delegation_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
390	ALTER TABLE delegation_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
391	ALTER TABLE sheet_role_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
