423	-- The sheet's holidays: a claim's due-by, fixed when it is made, that falls on one is moved to the next day that is not
424	-- a holiday. Each date at most once per sheet. Kept in history too (see V39 and V40).
425	CREATE TABLE holiday (
426	    sheet_id VARCHAR(255) NOT NULL,
427	    holiday_date DATE NOT NULL,
428	    PRIMARY KEY (sheet_id, holiday_date)
429	);
