435	CREATE TRIGGER holiday_journal AFTER INSERT, UPDATE, DELETE ON holiday FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
436	== V44__claim_ref.sql
437	-- A claim may carry an external reference (null: none), unique on its sheet without regard to case: ref_key is the
438	-- reference in lower case, which the unique index holds to once per sheet (nulls repeat freely). Kept in the claim's
439	-- history too (see V39). The journal trigger is made again around the change, as in V41.
440	DROP TRIGGER claim_journal;
