446	CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
447	== V45__claim_tags.sql
448	-- A claim may carry tags: kept trimmed, lower-cased, without repeats and sorted, comma separated (null: none). Kept in
449	-- the claim's history too (see V39), which is where every tag ever used on a sheet is read from. The journal trigger is
450	-- made again around the change, as in V41.
451	DROP TRIGGER claim_journal;
452	ALTER TABLE claim ADD COLUMN tags VARCHAR(4000);
453	ALTER TABLE claim_history ADD COLUMN tags VARCHAR(4000);
454	CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
455	== V46__void_reason.sql
456	-- The sheet's void reasons, listed in the order they were added; each reason at most once per sheet, without regard to
457	-- case. While a sheet has any, a claim is voided only with one of them, kept on the claim (null: voided without one, or
458	-- not voided). Kept in history too (see V39 and V40); the claim's journal trigger is made again around the change, as
459	-- in V41.
460	CREATE TABLE void_reason (
461	    sheet_id VARCHAR(255) NOT NULL,
462	    reason VARCHAR(255) NOT NULL,
463	    listed BIGINT NOT NULL,
464	    PRIMARY KEY (sheet_id, reason)
465	);
466	CREATE TABLE void_reason_history AS SELECT * FROM void_reason;
467	ALTER TABLE void_reason_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
468	ALTER TABLE void_reason_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
469	ALTER TABLE void_reason_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
470	CREATE INDEX void_reason_history_key ON void_reason_history (sheet_id, reason);
471	CREATE TRIGGER void_reason_journal AFTER INSERT, UPDATE, DELETE ON void_reason FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
472	DROP TRIGGER claim_journal;
473	ALTER TABLE claim ADD COLUMN void_reason VARCHAR(255);
474	ALTER TABLE claim_history ADD COLUMN void_reason VARCHAR(255);
475	CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
476	== V47__claim_comment.sql
477	-- A claim's comments, oldest first (by id): the text (trimmed, never empty), the user who wrote it and the sheet's
478	-- today when it was written. Kept in history too (see V39 and V40), so the as-of view shows them as they then were.
479	CREATE TABLE claim_comment (
480	    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
481	    sheet_id     VARCHAR(255)  NOT NULL,
482	    claim_id     BIGINT        NOT NULL REFERENCES claim (id),
483	    by_user      VARCHAR(255)  NOT NULL,
484	    commented_on DATE          NOT NULL,
485	    text         VARCHAR(4000) NOT NULL
486	);
487	CREATE INDEX claim_comment_sheet ON claim_comment (sheet_id, claim_id, id);
488	CREATE TABLE claim_comment_history AS SELECT * FROM claim_comment;
489	ALTER TABLE claim_comment_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
490	ALTER TABLE claim_comment_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
491	ALTER TABLE claim_comment_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
492	CREATE INDEX claim_comment_history_key ON claim_comment_history (sheet_id, id);
493	CREATE TRIGGER claim_comment_journal AFTER INSERT, UPDATE, DELETE ON claim_comment FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
494	== V48__claim_edited_by.sql
495	-- The user who last edited a claim (through its form or its row's amount entry; null when never edited). Like its
496	-- opener, they cannot settle or approve it. Kept in the claim's history too (see V39). The journal trigger is made
497	-- again around the change, as in V41.
498	DROP TRIGGER claim_journal;
499	ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
500	ALTER TABLE claim_history ADD COLUMN edited_by VARCHAR(255);
501	CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
502	== V50__settle_batch.sql
503	-- Settle batches: a bulk settle that settles at least one claim (one going to PENDING counts) is a batch, numbered
504	-- 1, 2, ... on the sheet in the order they happen (settle_batch, one row each). claim_batch is the batch that last
505	-- settled each claim; settling a claim one at a time takes it out of its batch. Both kept in history too (see V39 and
506	-- V40), so the as-of view shows them as they then were.
507	CREATE TABLE settle_batch (
508	    sheet_id     VARCHAR(255) NOT NULL,
509	    batch_number INT          NOT NULL,
510	    by_user      VARCHAR(255) NOT NULL,
511	    PRIMARY KEY (sheet_id, batch_number)
512	);
513	CREATE TABLE claim_batch (
514	    claim_id     BIGINT       NOT NULL PRIMARY KEY REFERENCES claim (id),
515	    sheet_id     VARCHAR(255) NOT NULL,
516	    batch_number INT          NOT NULL
517	);
518	CREATE INDEX claim_batch_sheet ON claim_batch (sheet_id, claim_id);
