524	CREATE INDEX settle_batch_history_key ON settle_batch_history (sheet_id, batch_number);
525	CREATE TRIGGER settle_batch_journal AFTER INSERT, UPDATE, DELETE ON settle_batch FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
