532	CREATE TRIGGER claim_batch_journal AFTER INSERT, UPDATE, DELETE ON claim_batch FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
533	== V51__person_contact.sql
534	-- A person's contact, kept without surrounding spaces and lower-cased; null for none. No two people on a sheet share
535	-- one. Kept in the person's history too (see V39). The journal trigger is made again around the change, as in V41.
536	DROP TRIGGER person_journal;
