540	== V52__person_alias.sql
541	-- A person's aliases, kept without surrounding spaces. They share the names' uniqueness on the sheet, compared
542	-- without regard to case: alias_key is the lower-cased alias, unique on the sheet (an alias equal to a name is
543	-- refused by the app). The quick-add bar and the paste box find a person by an alias as well as by the name.
544	CREATE TABLE person_alias (
545	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
546	    person_id BIGINT       NOT NULL REFERENCES person (id),
547	    sheet_id  VARCHAR(255) NOT NULL,
548	    alias     VARCHAR(255) NOT NULL,
549	    alias_key VARCHAR(255) GENERATED ALWAYS AS (LOWER(alias))
550	);
551	ALTER TABLE person_alias ADD CONSTRAINT person_alias_sheet_key UNIQUE (sheet_id, alias_key);
552	CREATE INDEX person_alias_person ON person_alias (person_id);
553	== V53__claim_template.sql
554	-- The sheet's claim templates: a name (trimmed, at most once per sheet), an amount and a note. Saving a name again
555	-- replaces its amount and note. A claim made from a template copies them, so a later save does not alter it.
556	CREATE TABLE claim_template (
557	    sheet_id VARCHAR(255) NOT NULL,
558	    name VARCHAR(255) NOT NULL,
559	    amount DECIMAL(19, 2) NOT NULL,
560	    note VARCHAR(1000) NOT NULL,
561	    listed BIGINT NOT NULL,
562	    PRIMARY KEY (sheet_id, name)
563	);
564	== V54__pool.sql
565	-- The sheet's pools: a name (trimmed, at most once per sheet), listed in the order added.
566	CREATE TABLE pool (
567	    sheet_id VARCHAR(255) NOT NULL,
568	    name VARCHAR(255) NOT NULL,
569	    listed BIGINT NOT NULL,
570	    PRIMARY KEY (sheet_id, name)
571	);
572	-- A pool's members: a person of the sheet, at most once per pool, with a share percent (two decimals, above 0.00 and
573	-- at most 100.00). A person can be in several pools. A retired member's share counts 0.00 toward the pool's total.
574	CREATE TABLE pool_member (
575	    sheet_id VARCHAR(255) NOT NULL,
576	    pool_name VARCHAR(255) NOT NULL,
577	    person_id BIGINT NOT NULL,
578	    share DECIMAL(5, 2) NOT NULL,
579	    listed BIGINT NOT NULL,
580	    PRIMARY KEY (sheet_id, pool_name, person_id)
581	);
582	== V55__person_patron_named.sql
583	-- The order a person named their patrons in (a patron's share depends on it: the first named takes what is left
584	-- over): each link numbered from one sequence as it is made. Kept in the patrons' history too (see V40). The journal
585	-- trigger is made again around the change, as in V41.
586	DROP TRIGGER person_patron_journal;
587	CREATE SEQUENCE person_patron_named;
588	ALTER TABLE person_patron ADD COLUMN named BIGINT DEFAULT NEXT VALUE FOR person_patron_named NOT NULL;
589	ALTER TABLE person_patron_history ADD COLUMN named BIGINT;
590	CREATE TRIGGER person_patron_journal AFTER INSERT, UPDATE, DELETE ON person_patron FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
591	== V56__person_alias_history.sql
592	-- Aliases kept in history too (see V39 and V40), so the as-of view shows a person's aliases as they then were.
593	CREATE TABLE person_alias_history AS SELECT * FROM person_alias;
594	ALTER TABLE person_alias_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
595	ALTER TABLE person_alias_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
596	ALTER TABLE person_alias_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
597	CREATE INDEX person_alias_history_key ON person_alias_history (sheet_id, id);
598	CREATE TRIGGER person_alias_journal AFTER INSERT, UPDATE, DELETE ON person_alias FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
599	== V57__sheet_loaded.sql
600	-- The sheets that have been loaded, so a sheet may name only one that exists as its parent.
601	CREATE TABLE sheet_loaded (
602	    id VARCHAR(255) PRIMARY KEY
603	);
604	== V58__pool_nested.sql
605	-- A pool's members that are other pools: a pool is a member of at most one pool, with a share percent like a person's
606	-- (two decimals, above 0.00 and at most 100.00). A pool never contains itself through any chain, and a chain of pools is
607	-- at most three deep. Listed in one order with the pool's person members (the next listed of both tables).
608	CREATE TABLE pool_nested (
609	    sheet_id VARCHAR(255) NOT NULL,
610	    pool_name VARCHAR(255) NOT NULL,
611	    member_pool VARCHAR(255) NOT NULL,
612	    share DECIMAL(5, 2) NOT NULL,
613	    listed BIGINT NOT NULL,
614	    PRIMARY KEY (sheet_id, member_pool)
615	);
616	== V59__person_position.sql
617	-- A person's position in the sheet's list: the list (and everything worked out in list order) runs by position, lowest
618	-- first. A new person (added, imported or transferred in) goes after everyone on the sheet; moving a person up or down
619	-- swaps positions with their neighbour. Positions may have gaps (a person merged away or transferred out leaves one).
620	-- People stored before keep the order they were added in. Kept in the person's history too (see V39). The journal
621	-- trigger is made again around the change, as in V41.
622	DROP TRIGGER person_journal;
623	ALTER TABLE person ADD COLUMN list_position BIGINT;
624	UPDATE person SET list_position = id;
625	ALTER TABLE person ALTER COLUMN list_position SET NOT NULL;
626	ALTER TABLE person_history ADD COLUMN list_position BIGINT;
627	UPDATE person_history SET list_position = id;
628	CREATE TRIGGER person_journal AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
629	== V60__person_origin.sql
630	-- The sheet a person was transferred from (origin_sheet_id) and the name they had there (origin_name); both null for
631	-- a person who was not transferred in. A person transferred again keeps only the sheet they last came from. Kept in the
632	-- person's history too (see V39). The journal trigger is made again around the change, as in V41.
633	DROP TRIGGER person_journal;
634	ALTER TABLE person ADD COLUMN origin_sheet_id VARCHAR(255);
635	ALTER TABLE person ADD COLUMN origin_name VARCHAR(255);
636	ALTER TABLE person_history ADD COLUMN origin_sheet_id VARCHAR(255);
637	ALTER TABLE person_history ADD COLUMN origin_name VARCHAR(255);
638	CREATE TRIGGER person_journal AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
639	== V61__pool_member_dated.sql
640	-- A pool membership (a person's or a pool's) may run from a from-date to a to-date, both inclusive and each optional (null
641	-- is open-ended); the to-date is never before the from-date. A member whose dates do not include the sheet's today is left
642	-- out entirely: not in the pool's total share, not in its balance, and no cut.
643	ALTER TABLE pool_member ADD COLUMN from_date DATE;
644	ALTER TABLE pool_member ADD COLUMN to_date DATE;
645	ALTER TABLE pool_nested ADD COLUMN from_date DATE;
646	ALTER TABLE pool_nested ADD COLUMN to_date DATE;
647	== V62__person_retirement.sql
648	-- A person's past retirements: each from the date they were retired from to the day they were unretired. A claim
649	-- dated after the from-date and before the to-date of one is refused, as one after a current retirement is.
650	-- Kept in history too (see V39 and V40).
651	CREATE TABLE person_retirement (
652	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
653	    person_id BIGINT NOT NULL REFERENCES person (id),
654	    from_date DATE   NOT NULL,
655	    to_date   DATE   NOT NULL
656	);
657	CREATE INDEX person_retirement_person ON person_retirement (person_id, from_date);
658	CREATE TABLE person_retirement_history AS SELECT * FROM person_retirement;
659	ALTER TABLE person_retirement_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
660	ALTER TABLE person_retirement_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
661	ALTER TABLE person_retirement_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
662	CREATE INDEX person_retirement_history_key ON person_retirement_history (person_id, id);
663	CREATE TRIGGER person_retirement_journal AFTER INSERT, UPDATE, DELETE ON person_retirement FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
