file.content:
== V1__sheet.sql
-- A sheet's own settings. A sheet with no row here has never been changed: its today is the real date.
CREATE TABLE sheet (
    id         VARCHAR(255) PRIMARY KEY,
    today_date DATE NOT NULL
);
== V2__person.sql
-- The people on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255) NOT NULL,
    name     VARCHAR(255) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V3__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case. Names are stored without
-- surrounding spaces; name_key is the lower-cased name the uniqueness is kept on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(255) GENERATED ALWAYS AS (LOWER(name));
ALTER TABLE person ADD CONSTRAINT person_sheet_name UNIQUE (sheet_id, name_key);
== V4__claim.sql
-- A person's claims on a sheet, listed newest first (by id). The amount is 0.00 or more, in two
-- decimals; claim_date defaults to the sheet's today when the claim is made.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255)   NOT NULL,
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(4000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
== V5__rate.sql
-- A sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(255)  NOT NULL,
    grade    VARCHAR(1)    NOT NULL,
    rate     DECIMAL(9, 2) NOT NULL CHECK (rate >= 0),
    PRIMARY KEY (sheet_id, grade)
);
== V6__claim_status.sql
-- A claim's status: DRAFT when made; OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(16) DEFAULT 'DRAFT' NOT NULL;
== V7__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused.
-- A draft has none; voiding a claim clears it. claim_number_seq holds the last number each sheet gave.
ALTER TABLE claim ADD COLUMN claim_number BIGINT;
CREATE TABLE claim_number_seq (
    sheet_id    VARCHAR(255) PRIMARY KEY,
    last_number BIGINT NOT NULL
);
== V8__claim_settled_due.sql
-- A settled claim's due, fixed when it was settled: its amount times its person's grade's rate at that
-- moment. Null for a claim not settled, or settled while the grade had no rate (its due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(15, 2);
== V9__rate_from.sql
-- A rate may carry a from-date: a grade may have several rates, one per from-date. A rate with no
-- from-date (null) applies from the beginning of time. At most one rate per grade and from-date.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V10__claim_opened_by.sql
-- Who opened the claim: the signed-in user named by the open. Null for a claim never opened.
-- The user who opened a claim cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
== V11__person_version.sql
-- The version of a person, raised on every edit. An edit names the version its form loaded and is
-- refused when the person has been saved since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
== V12__statement.sql
-- A claim bound by its person's last statement: stated, at the figure it had then (stated_due; null when it
-- had none). It shows and totals that figure until the person's next statement, which rebinds every claim
-- of theirs that counts then and leaves the rest unbound.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);

-- The statements taken of a person, in the order taken (by id): their due-total then ("n/a" when it had
-- none), how many of their claims counted, and the sheet's today when it was taken.
CREATE TABLE statement (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255) NOT NULL,
    person_id  BIGINT       NOT NULL REFERENCES person (id),
    due_total  VARCHAR(32)  NOT NULL,
    claims     INT          NOT NULL,
    stated_on  DATE         NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
== V13__period.sql
-- A sheet's periods: a name unique on the sheet and a from and to date, inclusive. No two periods
-- of a sheet overlap (checked when one is added).
CREATE TABLE period (
    sheet_id  VARCHAR(255) NOT NULL,
    name      VARCHAR(255) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date),
    PRIMARY KEY (sheet_id, name)
);
== V14__period_closed.sql
-- A period can be closed. Closing fixes its due-total at that moment: closed_total is that figure
-- (null while the period is open), and later changes to rates do not alter it.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(15, 2);
== V15__person_retired.sql
-- The date a person is retired from (null when not retired). A person with one set counts as retired
-- at once, whatever the date; claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V16__person_held.sql
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own, the
-- sheet's or a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== V17__setting_role.sql
-- A sheet's settings, one value per key (clerk-limit: an amount with two decimals). A key with no
-- row, or a blank value, is not set (a clerk limit not set is no limit).
CREATE TABLE setting (
    sheet_id      VARCHAR(255) NOT NULL,
    setting_key   VARCHAR(64)  NOT NULL,
    setting_value VARCHAR(255) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key)
);
-- The role a sheet gives a user name: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);
== V18__person_patron.sql
-- The people a person names as their patrons: other people on the same sheet, each at most once.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL,
    patron_id BIGINT NOT NULL,
    PRIMARY KEY (person_id, patron_id)
);
== V19__person_grade_from.sql
-- A person's grade is dated: person.grade is the first grade they were given, which applies from the
-- beginning of time; each row here is a grade they were given from a date on. At most one per date.
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL,
    from_date DATE       NOT NULL,
    grade     VARCHAR(1) NOT NULL,
    PRIMARY KEY (person_id, from_date)
);
== V20__claim_corrects.sql
-- A correction (a claim with a negative amount) names, by number, the SETTLED claim of the same person it
-- corrects; null for any other claim. The amount's old "0 or more" check (unnamed) goes with its column, which is
-- rebuilt so that only a correction may be negative.
ALTER TABLE claim ADD COLUMN corrects BIGINT;
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(15, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
== V21__claim_period_number.sql
-- A claim's number becomes text: the sheet-wide 1, 2, ... or, while the sheet numbers by period, <period>-<n>
-- (X-<n> for a claim in no period). A correction names the number it corrects the same way.
-- claim_period_number_seq holds the last number each sheet gave in each period ('' is the no-period sequence).
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(300);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(300);
CREATE TABLE claim_period_number_seq (
    sheet_id    VARCHAR(255) NOT NULL,
    scope       VARCHAR(255) NOT NULL,
    last_number BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, scope)
);
== V22__claim_listed.sql
-- Where a claim stands in its sheet's newest-first list: the next on its sheet when it is made, and again
-- when it is reassigned to another person, so a moved claim lists as its new person's newest whatever its date.
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
== V23__claim_due_by.sql
-- A claim's due-by, fixed when it is made: its date plus the terms of its person's grade on that date
-- (the sheet's terms when the grade has none of its own). Claims made before terms were kept per grade
-- are due by their date plus the sheet's terms (14 when never set).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.setting_value AS INT) FROM setting s
    WHERE s.sheet_id = c.sheet_id AND s.setting_key = 'terms' AND s.setting_value <> ''), 14), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V24__claim_log.sql
-- A claim's status log, oldest first (by id): each status it has had, who gave it, the sheet's today then,
-- and its due as shown at that moment ("n/a" when it had none). Claims made before the log have none.
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255) NOT NULL,
    claim_id  BIGINT       NOT NULL REFERENCES claim (id),
    status    VARCHAR(16)  NOT NULL,
    by_user   VARCHAR(255) NOT NULL,
    logged_on DATE         NOT NULL,
    due       VARCHAR(32)  NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
== V25__person_hold.sql
-- A person's holds, each from its from-date to its to-date inclusive (no to-date: open-ended). A person may
-- have several over time. Only their OPEN (and PENDING) claims dated within a hold and not bound by a statement
-- are left out of the live totals. A person held before holds were dated is held from the beginning of time.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id, from_date);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V26__rate_to.sql
-- A rate may carry a to-date: it applies through that date (null: with no end). Never before its from-date.
ALTER TABLE rate ADD COLUMN to_date DATE;
== V27__period_person_total.sql
-- Closing a period fixes each person's due-total for it too: one row per person on the sheet at that
-- moment. Reopening drops them; a person added while it is closed has no row (their figure is 0.00).
CREATE TABLE period_person_total (
    sheet_id    VARCHAR(255)   NOT NULL,
    period_name VARCHAR(255)   NOT NULL,
    person_id   BIGINT         NOT NULL,
    total       DECIMAL(15, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
== V28__setting_from.sql
-- A setting that carries a figure (the clerk limit, the floor, the terms and each grade's terms, the late percent,
-- the cap) is dated: one value per from-date, in force from that date until the next one. A blank value is none
-- (no clerk limit, no cap). The policy date and the period numbering from-date stay undated, in setting.
CREATE TABLE setting_from (
    sheet_id      VARCHAR(255) NOT NULL,
    setting_key   VARCHAR(64)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(255) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- A value saved before settings were dated was in force on every date.
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM setting
    WHERE setting_key IN ('clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap');
DELETE FROM setting
    WHERE setting_key IN ('clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap');
== V29__claim_deferred_until.sql
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches it the claim counts
-- in no total, is not overdue, cannot be settled and is left unbound by a statement. Null: never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V30__claim_proofs.sql
-- How many proofs a claim has been given, raised by one at a time; 0 for a claim given none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
== V31__role_viewer.sql
-- A third role, viewer: sees everything and may change nothing. The role check is rebuilt to allow it.
CREATE TABLE sheet_role_new (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_new (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
== V32__claim_split_from.sql
-- A claim split off another names, by number, the claim it was split from; null for any other claim.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(64);
== V33__person_watch.sql
-- Who watches whom: one row per signed-in user watching a person, in the order they started watching
-- (id). Unwatching deletes the row, so watching again starts afresh at the end.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(255) NOT NULL
);
CREATE INDEX person_watch_person ON person_watch (person_id, id);
== V34__delegation.sql
-- A steward's delegation of the steward role to a user name, from a from-date to a to-date (inclusive). While the
-- sheet's today is inside the range the user acts as a steward; delegated_by is the steward who delegated.
CREATE TABLE delegation (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(255) NOT NULL,
    user_name    VARCHAR(255) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL,
    delegated_by VARCHAR(255) NOT NULL
);
CREATE INDEX delegation_sheet ON delegation (sheet_id, user_name);
== V35__sheet_archived.sql
-- An archived sheet keeps everything visible and refuses every change. Only a steward archives a sheet.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V36__person_terms.sql
-- A person's own terms in days, which come before those of their grade and of the sheet; null for none.
ALTER TABLE person ADD COLUMN terms INT;
== V37__claim_lock.sql
-- A claim whose editor a user has open: locked for every other user until saved or cancelled, or the sheet's today changes.
CREATE TABLE claim_lock (
    claim_id  BIGINT       PRIMARY KEY REFERENCES claim (id),
    sheet_id  VARCHAR(255) NOT NULL,
    locked_by VARCHAR(255) NOT NULL
);
CREATE INDEX claim_lock_sheet ON claim_lock (sheet_id);
== V38__period_soft_close.sql
-- A period can be soft-closed: its due-total (closed_total) and its people's figures (period_person_total) are fixed,
-- but claims dated in it can still change. A claim added while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== V39__history.sql
-- The history of the rows a person's figures are worked out from: every row a change writes to claim, person,
-- person_grade, person_hold, rate, setting or setting_from is copied to <table>_history (by the Journal trigger) with
-- the sheet's today when the change was made (history_on), in the order made (history_seq); a deleted row is copied
-- as it was, marked history_gone. A statement taken as of a date reads these tables back: each row as its last copy
-- made on or before that date left it. A column added to one of these tables must be added to its history too.
-- Rows stored before the history was kept were made at the beginning of time.
CREATE TABLE claim_history AS SELECT * FROM claim;
CREATE TABLE person_history AS SELECT * FROM person;
CREATE TABLE person_grade_history AS SELECT * FROM person_grade;
CREATE TABLE person_hold_history AS SELECT * FROM person_hold;
CREATE TABLE rate_history AS SELECT * FROM rate;
CREATE TABLE setting_history AS SELECT * FROM setting;
CREATE TABLE setting_from_history AS SELECT * FROM setting_from;

