== V41__claim_reminded.sql
-- An OPEN or PENDING claim can be reminded, once per sheet's today: the last sheet's today a reminder was written
-- (null: never reminded). Kept in the claim's history too (see V39). The journal trigger is made again around the
-- change: altering the table copies it, and a trigger left on would keep naming the copy's history.
DROP TRIGGER claim_journal;
ALTER TABLE claim ADD COLUMN reminded_on DATE;
ALTER TABLE claim_history ADD COLUMN reminded_on DATE;
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V42__holiday.sql
-- The sheet's holidays: a claim's due-by, fixed when it is made, that falls on one is moved to the next day that is not
-- a holiday. Each date at most once per sheet. Kept in history too (see V39 and V40).
CREATE TABLE holiday (
    sheet_id VARCHAR(255) NOT NULL,
    holiday_date DATE NOT NULL,
    PRIMARY KEY (sheet_id, holiday_date)
);
CREATE TABLE holiday_history AS SELECT * FROM holiday;
ALTER TABLE holiday_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE holiday_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE holiday_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
CREATE INDEX holiday_history_key ON holiday_history (sheet_id, holiday_date);
CREATE TRIGGER holiday_journal AFTER INSERT, UPDATE, DELETE ON holiday FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V44__claim_ref.sql
-- A claim may carry an external reference (null: none), unique on its sheet without regard to case: ref_key is the
-- reference in lower case, which the unique index holds to once per sheet (nulls repeat freely). Kept in the claim's
-- history too (see V39). The journal trigger is made again around the change, as in V41.
DROP TRIGGER claim_journal;
ALTER TABLE claim ADD COLUMN ref VARCHAR(4000);
ALTER TABLE claim ADD COLUMN ref_key VARCHAR(4000);
ALTER TABLE claim_history ADD COLUMN ref VARCHAR(4000);
ALTER TABLE claim_history ADD COLUMN ref_key VARCHAR(4000);
CREATE UNIQUE INDEX claim_ref_unique ON claim (sheet_id, ref_key);
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V45__claim_tags.sql
-- A claim may carry tags: kept trimmed, lower-cased, without repeats and sorted, comma separated (null: none). Kept in
-- the claim's history too (see V39), which is where every tag ever used on a sheet is read from. The journal trigger is
-- made again around the change, as in V41.
DROP TRIGGER claim_journal;
ALTER TABLE claim ADD COLUMN tags VARCHAR(4000);
ALTER TABLE claim_history ADD COLUMN tags VARCHAR(4000);
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V46__void_reason.sql
-- The sheet's void reasons, listed in the order they were added; each reason at most once per sheet, without regard to
-- case. While a sheet has any, a claim is voided only with one of them, kept on the claim (null: voided without one, or
-- not voided). Kept in history too (see V39 and V40); the claim's journal trigger is made again around the change, as
-- in V41.
CREATE TABLE void_reason (
    sheet_id VARCHAR(255) NOT NULL,
    reason VARCHAR(255) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, reason)
);
CREATE TABLE void_reason_history AS SELECT * FROM void_reason;
ALTER TABLE void_reason_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE void_reason_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
