ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN edited_by VARCHAR(255);
CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V50__settle_batch.sql
-- Settle batches: a bulk settle that settles at least one claim (one going to PENDING counts) is a batch, numbered
-- 1, 2, ... on the sheet in the order they happen (settle_batch, one row each). claim_batch is the batch that last
-- settled each claim; settling a claim one at a time takes it out of its batch. Both kept in history too (see V39 and
-- V40), so the as-of view shows them as they then were.
CREATE TABLE settle_batch (
    sheet_id     VARCHAR(255) NOT NULL,
    batch_number INT          NOT NULL,
    by_user      VARCHAR(255) NOT NULL,
    PRIMARY KEY (sheet_id, batch_number)
);
CREATE TABLE claim_batch (
    claim_id     BIGINT       NOT NULL PRIMARY KEY REFERENCES claim (id),
    sheet_id     VARCHAR(255) NOT NULL,
    batch_number INT          NOT NULL
);
CREATE INDEX claim_batch_sheet ON claim_batch (sheet_id, claim_id);

CREATE TABLE settle_batch_history AS SELECT * FROM settle_batch;
ALTER TABLE settle_batch_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE settle_batch_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE settle_batch_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
CREATE INDEX settle_batch_history_key ON settle_batch_history (sheet_id, batch_number);
CREATE TRIGGER settle_batch_journal AFTER INSERT, UPDATE, DELETE ON settle_batch FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';

CREATE TABLE claim_batch_history AS SELECT * FROM claim_batch;
ALTER TABLE claim_batch_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE claim_batch_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim_batch_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
CREATE INDEX claim_batch_history_key ON claim_batch_history (sheet_id, claim_id);
CREATE TRIGGER claim_batch_journal AFTER INSERT, UPDATE, DELETE ON claim_batch FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V51__person_contact.sql
-- A person's contact, kept without surrounding spaces and lower-cased; null for none. No two people on a sheet share
-- one. Kept in the person's history too (see V39). The journal trigger is made again around the change, as in V41.
DROP TRIGGER person_journal;
ALTER TABLE person ADD COLUMN contact VARCHAR(255);
ALTER TABLE person_history ADD COLUMN contact VARCHAR(255);
CREATE TRIGGER person_journal AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V52__person_alias.sql
-- A person's aliases, kept without surrounding spaces. They share the names' uniqueness on the sheet, compared
-- without regard to case: alias_key is the lower-cased alias, unique on the sheet (an alias equal to a name is
-- refused by the app). The quick-add bar and the paste box find a person by an alias as well as by the name.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    sheet_id  VARCHAR(255) NOT NULL,
    alias     VARCHAR(255) NOT NULL,
    alias_key VARCHAR(255) GENERATED ALWAYS AS (LOWER(alias))
);
ALTER TABLE person_alias ADD CONSTRAINT person_alias_sheet_key UNIQUE (sheet_id, alias_key);
CREATE INDEX person_alias_person ON person_alias (person_id);
== V53__claim_template.sql
-- The sheet's claim templates: a name (trimmed, at most once per sheet), an amount and a note. Saving a name again
-- replaces its amount and note. A claim made from a template copies them, so a later save does not alter it.
CREATE TABLE claim_template (
    sheet_id VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    amount DECIMAL(19, 2) NOT NULL,
    note VARCHAR(1000) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
== V54__pool.sql
-- The sheet's pools: a name (trimmed, at most once per sheet), listed in the order added.
CREATE TABLE pool (
    sheet_id VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
-- A pool's members: a person of the sheet, at most once per pool, with a share percent (two decimals, above 0.00 and
-- at most 100.00). A person can be in several pools. A retired member's share counts 0.00 toward the pool's total.
CREATE TABLE pool_member (
    sheet_id VARCHAR(255) NOT NULL,
    pool_name VARCHAR(255) NOT NULL,
    person_id BIGINT NOT NULL,
    share DECIMAL(5, 2) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, pool_name, person_id)
);
== V55__person_patron_named.sql
-- The order a person named their patrons in (a patron's share depends on it: the first named takes what is left
-- over): each link numbered from one sequence as it is made. Kept in the patrons' history too (see V40). The journal
-- trigger is made again around the change, as in V41.
DROP TRIGGER person_patron_journal;
CREATE SEQUENCE person_patron_named;
ALTER TABLE person_patron ADD COLUMN named BIGINT DEFAULT NEXT VALUE FOR person_patron_named NOT NULL;
ALTER TABLE person_patron_history ADD COLUMN named BIGINT;
CREATE TRIGGER person_patron_journal AFTER INSERT, UPDATE, DELETE ON person_patron FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V56__person_alias_history.sql
-- Aliases kept in history too (see V39 and V40), so the as-of view shows a person's aliases as they then were.
CREATE TABLE person_alias_history AS SELECT * FROM person_alias;
ALTER TABLE person_alias_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE person_alias_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE person_alias_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
CREATE INDEX person_alias_history_key ON person_alias_history (sheet_id, id);
CREATE TRIGGER person_alias_journal AFTER INSERT, UPDATE, DELETE ON person_alias FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V57__sheet_loaded.sql
-- The sheets that have been loaded, so a sheet may name only one that exists as its parent.
CREATE TABLE sheet_loaded (
    id VARCHAR(255) PRIMARY KEY
);
== V58__pool_nested.sql
-- A pool's members that are other pools: a pool is a member of at most one pool, with a share percent like a person's
-- (two decimals, above 0.00 and at most 100.00). A pool never contains itself through any chain, and a chain of pools is
-- at most three deep. Listed in one order with the pool's person members (the next listed of both tables).
CREATE TABLE pool_nested (
    sheet_id VARCHAR(255) NOT NULL,
    pool_name VARCHAR(255) NOT NULL,
    member_pool VARCHAR(255) NOT NULL,
    share DECIMAL(5, 2) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, member_pool)
);
== V59__person_position.sql
-- A person's position in the sheet's list: the list (and everything worked out in list order) runs by position, lowest
-- first. A new person (added, imported or transferred in) goes after everyone on the sheet; moving a person up or down
-- swaps positions with their neighbour. Positions may have gaps (a person merged away or transferred out leaves one).
-- People stored before keep the order they were added in. Kept in the person's history too (see V39). The journal
-- trigger is made again around the change, as in V41.
DROP TRIGGER person_journal;
ALTER TABLE person ADD COLUMN list_position BIGINT;
UPDATE person SET list_position = id;
ALTER TABLE person ALTER COLUMN list_position SET NOT NULL;
ALTER TABLE person_history ADD COLUMN list_position BIGINT;
UPDATE person_history SET list_position = id;
CREATE TRIGGER person_journal AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V60__person_origin.sql
-- The sheet a person was transferred from (origin_sheet_id) and the name they had there (origin_name); both null for
-- a person who was not transferred in. A person transferred again keeps only the sheet they last came from. Kept in the
-- person's history too (see V39). The journal trigger is made again around the change, as in V41.
DROP TRIGGER person_journal;
ALTER TABLE person ADD COLUMN origin_sheet_id VARCHAR(255);
ALTER TABLE person ADD COLUMN origin_name VARCHAR(255);
ALTER TABLE person_history ADD COLUMN origin_sheet_id VARCHAR(255);
ALTER TABLE person_history ADD COLUMN origin_name VARCHAR(255);
CREATE TRIGGER person_journal AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
== V61__pool_member_dated.sql
-- A pool membership (a person's or a pool's) may run from a from-date to a to-date, both inclusive and each optional (null
-- is open-ended); the to-date is never before the from-date. A member whose dates do not include the sheet's today is left
-- out entirely: not in the pool's total share, not in its balance, and no cut.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
ALTER TABLE pool_nested ADD COLUMN from_date DATE;
ALTER TABLE pool_nested ADD COLUMN to_date DATE;
== V62__person_retirement.sql
-- A person's past retirements: each from the date they were retired from to the day they were unretired. A claim
-- dated after the from-date and before the to-date of one is refused, as one after a current retirement is.
-- Kept in history too (see V39 and V40).
CREATE TABLE person_retirement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE   NOT NULL
);
CREATE INDEX person_retirement_person ON person_retirement (person_id, from_date);
CREATE TABLE person_retirement_history AS SELECT * FROM person_retirement;
ALTER TABLE person_retirement_history ADD COLUMN history_on DATE DEFAULT DATE '0001-01-01' NOT NULL;
ALTER TABLE person_retirement_history ADD COLUMN history_gone BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE person_retirement_history ADD COLUMN history_seq BIGINT GENERATED BY DEFAULT AS IDENTITY;
CREATE INDEX person_retirement_history_key ON person_retirement_history (person_id, id);
CREATE TRIGGER person_retirement_journal AFTER INSERT, UPDATE, DELETE ON person_retirement FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';

