76	        jdbc.query("SELECT r.* FROM " + AsOf.table("person_retirement", "r") + " JOIN " + AsOf.table("person", "p") + " ON p.id = r.person_id WHERE p.sheet_id = ? "
77	                + "ORDER BY r.from_date, r.id", rs -> {
