106	    /**
107	     * The sheets of the sheet's tree: the sheet itself, its ancestors (its parent, their parent and so on) and its
108	     * descendants (the sheets naming it as their parent, their children and so on), each once. Not dated, like the parent.
109	     */
110	    public Set<String> tree(String sheetId) {
111	        Set<String> tree = new LinkedHashSet<>(List.of(sheetId));
112	        String at = sheetId;
113	        while (true) {
114	            List<String> parent = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet_id = ? AND setting_key = 'parent'",
115	                    String.class, at);
116	            if (parent.isEmpty() || parent.get(0).isBlank() || !tree.add(parent.get(0).trim())) {
117	                break;
118	            }
119	            at = parent.get(0).trim();
120	        }
121	        Deque<String> todo = new ArrayDeque<>(List.of(sheetId));
122	        while (!todo.isEmpty()) {
123	            for (String child : jdbc.queryForList("SELECT sheet_id FROM setting WHERE setting_key = 'parent' AND setting_value = ?",
124	                    String.class, todo.pop())) {
125	                if (tree.add(child)) {
126	                    todo.add(child);
127	                }
128	            }
129	        }
130	        return tree;
131	    }
