133	    /** The lower-cased names and aliases of everyone on the sheet's tree but the person {@code exceptId}. */
134	    private Set<String> namesInTree(String sheetId, long exceptId) {
135	        Set<String> names = new HashSet<>();
136	        for (String sheet : tree(sheetId)) {
137	            names.addAll(jdbc.queryForList("SELECT LOWER(name) FROM " + AsOf.table("person") + " WHERE sheet_id = ? AND id <> ?",
138	                    String.class, sheet, exceptId));
139	            names.addAll(jdbc.queryForList("SELECT LOWER(alias) FROM " + AsOf.table("person_alias") + " WHERE sheet_id = ? AND person_id <> ?",
140	                    String.class, sheet, exceptId));
141	        }
142	        return names;
143	    }
