176	     * The ids of the sheet's people who clash: whose name or any alias is a name or alias of someone else on the sheet's
177	     * tree, ignoring case (people who were on the sheet before a name was refused across its tree).
178	     */
179	    public Set<Long> clashing(String sheetId) {
180	        Map<String, Set<Long>> users = new HashMap<>();
181	        for (String sheet : tree(sheetId)) {
182	            jdbc.query("SELECT id, LOWER(name) FROM " + AsOf.table("person") + " WHERE sheet_id = ?",
183	                    rs -> { users.computeIfAbsent(rs.getString(2), k -> new HashSet<>()).add(rs.getLong(1)); }, sheet);
184	            jdbc.query("SELECT person_id, LOWER(alias) FROM " + AsOf.table("person_alias") + " WHERE sheet_id = ?",
185	                    rs -> { users.computeIfAbsent(rs.getString(2), k -> new HashSet<>()).add(rs.getLong(1)); }, sheet);
186	        }
187	        Set<Long> own = new HashSet<>(jdbc.queryForList("SELECT id FROM " + AsOf.table("person") + " WHERE sheet_id = ?", Long.class, sheetId));
188	        Set<Long> clashing = new HashSet<>();
189	        users.values().stream().filter(ids -> ids.size() > 1).forEach(ids -> ids.stream().filter(own::contains).forEach(clashing::add));
190	        return clashing;
191	    }
