257	    /**
258	     * Merge the person {@code from} into {@code into}: from's claims move to into (numbers and dates kept, unbound from
259	     * any statement, listed after into's claims in the order they were added); from's name and aliases become into's
260	     * aliases; from's patrons are added to into's and anyone naming from names into instead (never themselves, no
261	     * repeats); from's pool memberships and closed-period figures move to into (added to into's own where into has
262	     * one). from's statements, holds, watchers, grades and contact are dropped, and from leaves the sheet.
263	     */
264	    public void merge(String sheetId, long from, long into) {
265	        for (Long claim : jdbc.queryForList("SELECT id FROM claim WHERE person_id = ? ORDER BY listed, id", Long.class, from)) {
266	            jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, listed = "
267	                    + "(SELECT COALESCE(MAX(listed), 0) + 1 FROM claim WHERE sheet_id = ?) WHERE id = ?", into, sheetId, claim);
268	        }
269	        String name = jdbc.queryForObject("SELECT name FROM person WHERE id = ?", String.class, from);
270	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE person_id = ?", into, from);
271	        for (Long patron : jdbc.queryForList("SELECT patron_id FROM person_patron WHERE person_id = ? ORDER BY named", Long.class, from)) {
272	            linkPatron(into, patron);
273	        }
274	        for (Long person : jdbc.queryForList("SELECT person_id FROM person_patron WHERE patron_id = ?", Long.class, from)) {
275	            linkPatron(person, into);
276	        }
277	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", from, from);
278	        for (Map<String, Object> m : jdbc.queryForList("SELECT pool_name, share FROM pool_member WHERE sheet_id = ? AND person_id = ?",
279	                sheetId, from)) {
280	            if (jdbc.update("UPDATE pool_member SET share = share + ? WHERE sheet_id = ? AND pool_name = ? AND person_id = ?",
281	                    m.get("share"), sheetId, m.get("pool_name"), into) == 0) {
282	                jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND pool_name = ? AND person_id = ?",
283	                        into, sheetId, m.get("pool_name"), from);
284	            }
285	        }
286	        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", sheetId, from);
287	        for (Map<String, Object> m : jdbc.queryForList("SELECT period_name, total FROM period_person_total WHERE sheet_id = ? AND person_id = ?",
288	                sheetId, from)) {
289	            if (jdbc.update("UPDATE period_person_total SET total = total + ? WHERE sheet_id = ? AND period_name = ? AND person_id = ?",
290	                    m.get("total"), sheetId, m.get("period_name"), into) == 0) {
291	                jdbc.update("UPDATE period_person_total SET person_id = ? WHERE sheet_id = ? AND period_name = ? AND person_id = ?",
292	                        into, sheetId, m.get("period_name"), from);
293	            }
294	        }
295	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", sheetId, from);
296	        jdbc.update("DELETE FROM statement WHERE person_id = ?", from);
297	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", from);
298	        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", from);
299	        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", from);
300	        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", from);
301	        jdbc.update("DELETE FROM person WHERE id = ?", from);
302	        alias(sheetId, into, name);
