305	    /**
306	     * Transfer the person to the sheet {@code to}, returning their id there. They arrive with their first grade and every
307	     * grade given since (with its from-date), their terms, contact and aliases, and their claims (listed in the order
308	     * they were, as the newest on that sheet) with their status, dates, notes, frozen figures, comments and logs; a
309	     * claim in {@code numbers} takes the number given there. The figures a statement bound and the references are not
310	     * carried. They leave their sheet entirely: their claims, statements, holds, watches, patron links, pool memberships
311	     * and closed-period figures are dropped with them.
312	     */
313	    public long transfer(Person person, String to, Map<Long, String> numbers) {
314	        long from = person.id();
315	        KeyHolder key = new GeneratedKeyHolder();
316	        jdbc.update(con -> {
317	            PreparedStatement ps = con.prepareStatement(
318	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, origin_sheet_id, origin_name, list_position) VALUES (?, ?, ?, ?, ?, ?, ?, "
319	                            + "(SELECT COALESCE(MAX(list_position), 0) + 1 FROM person WHERE sheet_id = ?))", new String[] { "id" });
320	            ps.setString(1, to);
321	            ps.setString(2, person.name());
322	            ps.setString(3, person.grade());
323	            ps.setObject(4, person.terms(), java.sql.Types.INTEGER);
324	            ps.setString(5, person.contact());
325	            ps.setString(6, person.sheetId());
326	            ps.setString(7, person.name());
327	            ps.setString(8, to);
328	            return ps;
329	        }, key);
330	        long arrived = key.getKey().longValue();
331	        jdbc.update("INSERT INTO person_grade (person_id, from_date, grade) SELECT ?, from_date, grade FROM person_grade "
332	                + "WHERE person_id = ? ORDER BY from_date", arrived, from);
333	        jdbc.update("INSERT INTO person_alias (person_id, sheet_id, alias) SELECT ?, ?, alias FROM person_alias "
334	                + "WHERE person_id = ? ORDER BY id", arrived, to, from);
335	        List<Long> claims = jdbc.queryForList("SELECT id FROM claim WHERE person_id = ? ORDER BY listed, id", Long.class, from);
336	        for (Long claim : claims) {
337	            KeyHolder claimKey = new GeneratedKeyHolder();
338	            jdbc.update(con -> {
339	                PreparedStatement ps = con.prepareStatement(
340	                        "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, "
341	                                + "opened_by, corrects, due_by, deferred_until, proofs, split_from, late_entry, reminded_on, tags, "
342	                                + "void_reason, edited_by, due_terms, listed) "
343	                                + "SELECT ?, ?, amount, claim_date, note, status, ?, settled_due, opened_by, corrects, due_by, "
344	                                + "deferred_until, proofs, split_from, late_entry, reminded_on, tags, void_reason, edited_by, due_terms, "
345	                                + "(SELECT COALESCE(MAX(listed), 0) + 1 FROM claim WHERE sheet_id = ?) FROM claim WHERE id = ?",
346	                        new String[] { "id" });
347	                ps.setString(1, to);
348	                ps.setLong(2, arrived);
349	                ps.setString(3, numbers.get(claim));
350	                ps.setString(4, to);
351	                ps.setLong(5, claim);
352	                return ps;
353	            }, claimKey);
354	            long moved = claimKey.getKey().longValue();
355	            jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, logged_on, due) "
356	                    + "SELECT ?, ?, status, by_user, logged_on, due FROM claim_log WHERE claim_id = ? ORDER BY id", to, moved, claim);
357	            jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, commented_on, text) "
358	                    + "SELECT ?, ?, by_user, commented_on, text FROM claim_comment WHERE claim_id = ? ORDER BY id", to, moved, claim);
359	        }
360	        for (Long claim : claims) {
361	            jdbc.update("DELETE FROM claim_log WHERE claim_id = ?", claim);
362	            jdbc.update("DELETE FROM claim_comment WHERE claim_id = ?", claim);
363	            jdbc.update("DELETE FROM claim_lock WHERE claim_id = ?", claim);
364	            jdbc.update("DELETE FROM claim_batch WHERE claim_id = ?", claim);
365	            jdbc.update("DELETE FROM claim WHERE id = ?", claim);
366	        }
367	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", from, from);
368	        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", person.sheetId(), from);
369	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", person.sheetId(), from);
370	        jdbc.update("DELETE FROM statement WHERE person_id = ?", from);
371	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", from);
372	        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", from);
373	        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", from);
374	        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", from);
375	        jdbc.update("DELETE FROM person_alias WHERE person_id = ?", from);
376	        jdbc.update("DELETE FROM person WHERE id = ?", from);
377	        return arrived;
378	    }
