453	    public Figures figures(String sheetId) {
454	        LocalDate today = sheets.today(sheetId);
455	        List<Claim> counting = claims.list(sheetId).stream()
456	                .filter(c -> c.status().counts()).toList();
457	        Map<Long, Figures.PersonFigures> figures = new LinkedHashMap<>();
458	        BigDecimal claimedTotal = ZERO;
459	        List<BigDecimal> dues = new ArrayList<>();
460	        List<BigDecimal> overdues = new ArrayList<>();
461	        for (Person person : people.list(sheetId)) {
462	            BigDecimal claimed = ZERO;
463	            BigDecimal due = ZERO;
464	            BigDecimal overdue = ZERO;
465	            boolean anyFigure = false;
466	            for (Claim claim : counting) {
467	                if (claim.personId() != person.id() || !counts(claim, person, today)) {
468	                    continue;
469	                }
470	                claimed = claimed.add(claim.amount());
471	                BigDecimal figure = figure(claim, person, today);
472	                if (figure != null) {
473	                    due = due.add(figure);
474	                    anyFigure = true;
475	                    if (settings.overdue(claim, today)) {
476	                        overdue = overdue.add(figure);
477	                    }
478	                }
479	            }
480	            // With no rate today and no figure, the due-total is n/a.
481	            boolean none = !anyFigure && rates.on(sheetId, person.gradeOn(today), today) == null;
482	            // Otherwise it is held to the sheet's cap.
483	            due = settings.capped(sheetId, due);
484	            claimedTotal = claimedTotal.add(claimed);
485	            if (!none) {
486	                dues.add(due);
487	            }
488	            overdues.add(overdue);
489	            figures.put(person.id(), new Figures.PersonFigures(person.name(), claimed.toPlainString(),
490	                    none ? "n/a" : due.toPlainString(), overdue.toPlainString()));
491	        }
492	        return new Figures(figures, claimedTotal.toPlainString(), trimmed(dues).toPlainString(),
493	                trimmed(overdues).toPlainString());
494	    }
495	
496	    /** A sheet total of per-person figures: with three or more, the single highest and lowest are left out. */
497	    private static BigDecimal trimmed(List<BigDecimal> figures) {
498	        List<BigDecimal> sorted = figures.stream().sorted().toList();
499	        List<BigDecimal> kept = sorted.size() >= 3 ? sorted.subList(1, sorted.size() - 1) : sorted;
500	        return kept.stream().reduce(ZERO, BigDecimal::add);
501	    }
502	
503	    /**
504	     * Each person's due-total for the dates {@code from} to {@code to} inclusive, by person id in sheet order: the
505	     * figures (as shown now) of their claims due by a date then that counted by the status their log records at the end of
506	     * {@code to} (a claim added after it counts not at all), those without one skipped.
507	     */
508	    public Map<Long, BigDecimal> personDueTotals(String sheetId, LocalDate from, LocalDate to) {
509	        LocalDate today = sheets.today(sheetId);
510	        Map<Long, ClaimStatus> ended = claims.statusesOn(sheetId, to);
511	        List<Claim> dated = claims.list(sheetId).stream()
512	                .filter(c -> !c.dueBy().isBefore(from) && !c.dueBy().isAfter(to)).toList();
513	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
514	        for (Person person : people.list(sheetId)) {
515	            BigDecimal total = ZERO;
516	            for (Claim claim : dated) {
517	                Claim then = claim.withStatus(ended.getOrDefault(claim.id(), claim.status()), claim.number(),
518	                        claim.settledDue(), claim.openedBy());
519	                // A hold leaves out only a claim that is open now.
520	                boolean left = claim.status().isOpen() ? !counts(then, person, today) : then.deferredOn(today);
521	                if (claim.personId() != person.id() || !then.status().counts() || left) {
522	                    continue;
523	                }
524	                BigDecimal figure = figure(claim, person, today);
525	                if (figure != null) {
526	                    total = total.add(figure);
527	                }
528	            }
529	            totals.put(person.id(), total);
530	        }
531	        return totals;
532	    }
533	
534	    /** The claim's figure as the screen shows it on the sheet's today (null: n/a), whatever its status. */
535	    public BigDecimal figure(Claim claim) {
536	        Person person = people.find(claim.sheetId(), claim.personId());
537	        return person == null ? claim.settledDue() : figure(claim, person, sheets.today(claim.sheetId()));
538	    }
539	
540	    /**
541	     * Whether the (OPEN, PENDING or SETTLED) claim counts: a person's open claims dated within one of their holds
542	     * count in no live total, unless a statement bound them, nor do they once {@code today} reaches their retirement date;
543	     * nor does an OPEN claim deferred on {@code today}.
544	     */
545	    public static boolean counts(Claim claim, Person person, LocalDate today) {
546	        if (claim.deferredOn(today)) {
547	            return false;
548	        }
549	        boolean bound = claim.stated() && claim.status() != ClaimStatus.PENDING;
550	        return !(claim.status().isOpen() && !bound && (person.heldOn(claim.date()) || person.retiredOn(today)));
551	    }
552	
553	    /**
554	     * The claim's figure (null when it has none): a settled claim's frozen due, otherwise the figure its person's
555	     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, rounded by the policy date;
556	     * an overdue claim's late charge on {@code today} added on top of the last two, then raised to the floor.
557	     */
558	    private BigDecimal figure(Claim claim, Person person, LocalDate today) {
559	        if (claim.settledDue() != null) {
560	            return claim.settledDue();
561	        }
562	        return settings.withLate(claim, bound(claim, person), today);
563	    }
564	
565	    /**
566	     * The claim's figure before any late charge: the one its person's last statement bound, else its live rate figure (not floored).
567	     * A PENDING claim is not bound: it shows its live figure until approved or rejected.
568	     */
569	    private BigDecimal bound(Claim claim, Person person) {
570	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
571	            return claim.statedDue();
572	        }
573	        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
574	        return settings.live(claim, rate);
575	    }
576	}
