579	import java.io.IOException;
580	import java.io.UncheckedIOException;
581	import java.nio.charset.StandardCharsets;
582	import java.nio.file.Files;
583	import java.nio.file.Path;
584	import java.nio.file.StandardOpenOption;
585	import net.officefloor.server.http.HttpHeader;
586	import net.officefloor.server.http.ServerHttpConnection;
587	import java.util.ArrayList;
588	import java.util.Collections;
589	import java.util.List;
590	import java.util.Locale;
591	import java.util.Set;
592	import java.util.regex.Matcher;
593	import java.util.regex.Pattern;
594	import net.officefloor.hq.app.setting.Settings;
595	import org.springframework.beans.factory.ObjectProvider;
596	import org.springframework.beans.factory.annotation.Value;
597	import org.springframework.stereotype.Service;
598	
599	/**
600	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
601	 * so tests can assert side-effects by reading that file — the second test-assertion channel
602	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
603	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
604	 *
605	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
606	 * SYNC) so a test reads the record immediately.
607	 */
608	@Service
609	public class Audit {
610	
611	    /** The lines that only report figures: they never name the steward a change is made for. */
612	    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");
613	
614	    private final Path file;
615	    private final ObjectProvider<Settings> settings;
616	
617	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<Settings> settings) {
618	        this.file = Path.of(path);
619	        this.settings = settings;
620	    }
621	
622	    /**
623	     * Append one audit record. Tests assert the exact line(s) in the file. A change made by a user the steward role is
624	     * delegated to (for the sheet's today) ends with for=<the steward who delegated>, unless the line only reports figures.
625	     */
626	    public void record(String entry) {
627	        record(entry, null);
628	    }
629	
630	    /**
631	     * Append one audit record about the sheet as it stood on {@code on} (null: the sheet's today): a line by a user the
632	     * steward role was delegated to for that date ends with for=<the steward who delegated>, as {@link #record(String)}.
633	     */
634	    public synchronized void record(String entry, java.time.LocalDate on) {
635	        String delegator = delegator(entry, on);
636	        if (delegator != null) {
637	            entry = entry + " for=" + delegator;
638	        }
639	        try {
640	            Path parent = file.toAbsolutePath().getParent();
641	            if (parent != null) {
642	                Files.createDirectories(parent);
643	            }
644	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
645	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
646	        } catch (IOException e) {
647	            throw new UncheckedIOException(e);
648	        }
649	    }
650	
651	    /** The steward who delegated to the user the line is by, on the line's sheet; null when none did or the line only reports figures. */
652	    private String delegator(String entry, java.time.LocalDate on) {
653	        String[] parts = entry.split(" ", 4);
654	        if (parts.length < 3 || FIGURES.contains(parts[0]) || !parts[1].startsWith("sheet=") || !parts[2].startsWith("by=")) {
655	            return null;
656	        }
657	        String sheetId = parts[1].substring("sheet=".length());
658	        String user = parts[2].substring("by=".length());
659	        return on == null ? settings.getObject().delegator(sheetId, user) : settings.getObject().delegator(sheetId, user, on);
660	    }
661	
662	    /** The signed-in user a write names in its X-User header ("" when it names none). */
663	    public static String user(ServerHttpConnection connection) {
664	        HttpHeader header = connection.getRequest().getHeaders().getHeader("X-User");
665	        return header == null ? "" : header.getValue();
666	    }
667	
668	    /** One record: the event, then sheet=<id> and by=<user>, then the fields, separated by single spaces. */
669	    public static String line(String event, String sheetId, String user, String... fields) {
670	        StringBuilder line = new StringBuilder(event).append(" sheet=").append(sheetId)
671	                .append(" by=").append(user == null ? "" : user.trim());
672	        for (String field : fields) {
673	            line.append(' ').append(field);
674	        }
675	        return line.toString();
676	    }
677	
678	    /**
679	     * The sheet's lines exactly as the file holds them, newest first. With a name (not blank), only the lines about that
680	     * person: those carrying name=<the name> or person=<the name>, compared as names are (case and surrounding spaces ignored).
681	     */
682	    public synchronized List<String> lines(String sheetId, String name) {
683	        String wanted = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
684	        List<String> all;
685	        try {
686	            all = Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
687	        } catch (IOException e) {
688	            throw new UncheckedIOException(e);
689	        }
690	        List<String> lines = new ArrayList<>();
691	        for (String line : all) {
692	            String[] parts = line.split(" ", 3);
693	            if (parts.length >= 2 && parts[1].equals("sheet=" + sheetId)
694	                    && (wanted.isEmpty() || names(line).contains(wanted))) {
695	                lines.add(line);
696	            }
697	        }
698	        Collections.reverse(lines);
699	        return lines;
700	    }
701	
702	    /** The values of a line's name= and person= fields, trimmed and lower-cased; a value runs up to the next field. */
703	    private static List<String> names(String line) {
704	        List<String> names = new ArrayList<>();
705	        Matcher m = NAME_FIELD.matcher(line);
706	        while (m.find()) {
707	            names.add(m.group(1).trim().toLowerCase(Locale.ROOT));
708	        }
709	        return names;
710	    }
711	
712	    private static final Pattern NAME_FIELD = Pattern.compile(" (?:name|person)=(.*?)(?= [A-Za-z][\\w-]*=|$)");
713	
714	    /** Remove the audit file. */
715	    public synchronized void clear() {
716	        try {
717	            Files.deleteIfExists(file);
718	        } catch (IOException e) {
719	            throw new UncheckedIOException(e);
720	        }
721	    }
722	}
